export type Category = 'calzados' | 'prendas' | 'accesorios'

/** Un producto = un SKU del stock. Los talles son las filas del CSV agrupadas. */
export type Product = {
  id: string
  sku: string
  /** Código interno, correlativo: sirve para ordenar por ingreso. */
  code: number
  name: string
  brand: string
  category: Category
  /** Categoría fina del stock: "Calzado deportivo", "Bolsos y mochilas", … */
  subcategory: string
  gender?: string
  price: number
  /** Precio anterior tachado. Descuento de demo, no viene del stock. */
  compareAt?: number
  /** Fecha de carga al stock (columna `cargado` del CSV). */
  addedAt: string
  images: string[]
  sizes: string[]
  colors: string[]
  stock: number
  description: string
}

