export const getProduct = (id: string) => products.find((p) => p.id === id)

export const related = (p: Product, n = 8) =>
  products.filter((x) => x.id !== p.id && (x.subcategory === p.subcategory || x.brand === p.brand)).slice(0, n)

/** Últimos ingresos según la fecha de carga al stock. */
export const latest = (n = 8) =>
  [...products].sort((a, b) => b.addedAt.localeCompare(a.addedAt) || b.code - a.code).slice(0, n)

/** Productos con descuento vigente. */
export const onSale = (n = 8) => products.filter((p) => p.compareAt).slice(0, n)
